SELECT EXISTS(
    SELECT 1 FROM enrollments
    WHERE student_id = (SELECT id FROM students WHERE user_id = #{studentId}) AND lecture_id = #{lectureId}
)

SELECT capacity FROM lectures
WHERE id = #{lectureId}
FOR UPDATE

SELECT c.credits FROM lectures l
JOIN courses c ON l.course_id = c.id
WHERE l.id = #{lectureId}
